CREATE TABLE IF NOT EXISTS `test_result`
(
    `id`                            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Surrogate key ID',
    `test_result_id`                VARCHAR(36) NOT NULL COMMENT 'Unique identifier for the test result, generated by the backend',
    `vehicle_id`                    BIGINT UNSIGNED NOT NULL COMMENT 'Vehicle surrogate key ID. References `[vehicle].[id]`',
    `test_station_id`               BIGINT UNSIGNED COMMENT 'Test station surrogate key ID. References `[test_station].[id]`. JOIN for name, p_number, and type.',
    `tester_name`                   VARCHAR(60) COMMENT 'Name of the Vehicle Standards Assessor who conducted the test',
    `tester_staff_id`               VARCHAR(36) COMMENT 'Staff ID of the Vehicle Standards Assessor',
    `tester_email_address`          VARCHAR(60) COMMENT 'Email address of the Vehicle Standards Assessor',
    `test_start_timestamp`          DATETIME(3) COMMENT 'The Date and Time the test started',
    `test_end_timestamp`            DATETIME(3) COMMENT 'The Date and Time the test ended',
    `test_status`                   VARCHAR(20) COMMENT 'Status of the test, e.g. submitted, cancelled',
    `reason_for_cancellation`       TEXT COMMENT 'Reason provided if the test was cancelled',
    `vehicle_type`                  VARCHAR(20) COMMENT 'Vehicle type at time of test, e.g. psv, hgv, trl, car, lgv, motorcycle',
    `vehicle_class_code`            VARCHAR(10) COMMENT 'Vehicle class code snapshot at time of test',
    `vehicle_class_description`     VARCHAR(100) COMMENT 'Vehicle class description snapshot at time of test',
    `vehicle_subclass`              JSON COMMENT 'JSON array of vehicle subclass values at time of test',
    `vehicle_configuration`         VARCHAR(50) COMMENT 'Vehicle configuration snapshot at time of test',
    `vehicle_size`                  VARCHAR(20) COMMENT 'Vehicle size snapshot at time of test, PSV only',
    `eu_vehicle_category`           VARCHAR(10) COMMENT 'EU vehicle category snapshot at time of test',
    `country_of_registration`       VARCHAR(50) COMMENT 'Country of registration snapshot at time of test',
    `no_of_axles`                   INT UNSIGNED COMMENT 'Number of axles snapshot at time of test',
    `number_of_wheels_driven`       INT UNSIGNED COMMENT 'Number of wheels driven snapshot at time of test',
    `number_of_seats`               INT UNSIGNED COMMENT 'Number of seats snapshot at time of test, PSV only',
    `regn_date`                     DATE COMMENT 'Registration date snapshot at time of test',
    `first_use_date`                DATE COMMENT 'First use date snapshot at time of test, TRL only',
    `make`                          VARCHAR(50) COMMENT 'Vehicle make snapshot at time of test',
    `model`                         VARCHAR(30) COMMENT 'Vehicle model snapshot at time of test',
    `body_type_code`                VARCHAR(10) COMMENT 'Body type code snapshot at time of test',
    `body_type_description`         VARCHAR(100) COMMENT 'Body type description snapshot at time of test',
    `odometer_reading`              INT UNSIGNED COMMENT 'Odometer reading recorded at time of test',
    `odometer_reading_units`        VARCHAR(20) COMMENT 'Odometer reading units, e.g. kilometres, miles',
    `preparer_id`                   VARCHAR(36) COMMENT 'ID of the preparer who prepared the vehicle for test',
    `preparer_name`                 VARCHAR(150) COMMENT 'Name of the preparer',
    `vrm`                           VARCHAR(9) COMMENT 'Vehicle Registration Mark at time of test',
    `trailer_id`                    VARCHAR(8) COMMENT 'Trailer ID at time of test, TRL only',
    `contingency_test_number`       VARCHAR(8) COMMENT 'Contingency test number if applicable',
    `type_of_test`                  VARCHAR(20) COMMENT 'Type of test, e.g. contingency, desk-based, completion',
    `source`                        VARCHAR(10) COMMENT 'Source system of the test result, e.g. vtm, vta',
    `vehicle_id_field`              VARCHAR(36) COMMENT 'Original vehicleId field from source system',
    `test_version`                  VARCHAR(10) COMMENT 'Version of the test result schema',
    `should_email_certificate`      VARCHAR(10) COMMENT 'Whether a certificate email should be sent',
    `reason_for_creation`           VARCHAR(100) COMMENT 'Reason for creating the test result record',
    `recalls_has_recall`            BOOLEAN COMMENT 'Whether a recall has been recorded against this vehicle at time of test',
    `recalls_manufacturer`          VARCHAR(100) COMMENT 'Manufacturer associated with the recall, if applicable',
    `weights_design_gross_vehicle_weight` INT UNSIGNED COMMENT 'Design gross vehicle weight in kg',
    `weights_design_gross_train_weight`   INT UNSIGNED COMMENT 'Design gross train weight in kg',
    `weights_design_gross_axle_weight`    INT UNSIGNED COMMENT 'Design gross axle weight in kg',
    `weights_design_train_weight_required` VARCHAR(10) COMMENT 'Whether design gross train weight is not applicable, e.g. N/A',
    `vtg15_required`                BOOLEAN COMMENT 'Whether a VTG15 (dangerous goods) declaration is required',
    `vtg15_un_number`                INT UNSIGNED COMMENT 'UN number of the dangerous goods carried',
    `vtg15_primary_hazard_classification`   VARCHAR(5) COMMENT 'Primary hazard classification code of the dangerous goods carried',
    `vtg15_secondary_hazard_classification` VARCHAR(5) COMMENT 'Secondary hazard classification code of the dangerous goods carried',
    `vtg15_media`                   JSON COMMENT 'JSON array of media references supporting the VTG15 declaration',
    `deletion_flag`                 BOOLEAN COMMENT 'Whether this test result has been soft-deleted',
    `created_by_id`                 VARCHAR(40) COMMENT 'ID of the user that originally created the record',
    `created_by_name`               VARCHAR(200) COMMENT 'Name of user that created the record',
    `created_by_email_address`      VARCHAR(255) COMMENT 'Email address of user that created the record',
    `inserted_datetime`             DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'The Date and Time the record was created',
    `last_updated_by_id`            VARCHAR(40) COMMENT 'ID of the user who last updated the record',
    `last_updated_by_name`          VARCHAR(200) COMMENT 'Name of the user that last updated the record',
    `last_updated_by_email_address` VARCHAR(255) COMMENT 'Email address of the user that last updated the record',
    `last_updated_datetime`         DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'The Date and Time the record was last updated',
    PRIMARY KEY (`id`),
    UNIQUE INDEX `idx_test_result_id_uq` (`test_result_id` ASC) COMMENT 'Enforces uniqueness on the test result ID and supports efficient lookups',
    CONSTRAINT `fk_test_result_vehicle_id` FOREIGN KEY (`vehicle_id`) REFERENCES `vehicle` (`id`),
    CONSTRAINT `fk_test_result_test_station_id` FOREIGN KEY (`test_station_id`) REFERENCES `test_station` (`id`),
    INDEX `idx_test_result_vehicle_id` (`vehicle_id` ASC) COMMENT 'Supports efficient lookups of all test results for a vehicle',
    INDEX `idx_test_result_test_station_id` (`test_station_id` ASC) COMMENT 'Supports efficient lookups of all test results at a test station',
    INDEX `idx_test_result_tester_staff_id` (`tester_staff_id` ASC) COMMENT 'Supports efficient lookups of all test results by a tester'
)
    ENGINE = InnoDB
    COMMENT = 'Test result records representing a test visit, with vehicle data snapshotted at the time of test for historical accuracy';

CREATE TABLE IF NOT EXISTS `test_result_test_type`
(
    `id`                                        BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Surrogate key ID',
    `test_result_id`                            BIGINT UNSIGNED NOT NULL COMMENT 'Test result surrogate key ID. References `[test_result].[id]`',
    `test_type_id`                              VARCHAR(10) NOT NULL COMMENT 'Test type identifier. JOIN to `[test_type].[id]` for name, test_type_name, and test_type_classification.',
    `test_number`                               VARCHAR(36) COMMENT 'Unique test number generated for this specific test type execution',
    `test_code`                                 VARCHAR(10) COMMENT 'Test code applied for this test type execution',
    `certificate_number`                        VARCHAR(36) COMMENT 'Certificate number issued for this test type, if applicable',
    `secondary_certificate_number`              VARCHAR(36) COMMENT 'Secondary certificate number, if applicable',
    `test_type_start_timestamp`                 DATETIME(3) COMMENT 'The Date and Time this specific test type started',
    `test_type_end_timestamp`                   DATETIME(3) COMMENT 'The Date and Time this specific test type ended',
    `test_result`                               VARCHAR(20) COMMENT 'Result of the test type, e.g. pass, prs, fail, abandoned',
    `prohibition_issued`                        BOOLEAN COMMENT 'Whether a prohibition was issued for this test type',
    `reason_for_abandoning`                     TEXT COMMENT 'Reason provided if the test type was abandoned',
    `additional_notes_recorded`                 VARCHAR(500) COMMENT 'Additional notes recorded by the tester',
    `additional_comments_for_abandon`           VARCHAR(500) COMMENT 'Additional comments provided when abandoning',
    `test_expiry_date`                          DATE COMMENT 'Date the test expires',
    `test_anniversary_date`                     DATE COMMENT 'Anniversary date for the test',
    `reapplication_date`                        DATE COMMENT 'Date the vehicle can reapply for testing',
    `number_of_seatbelts_fitted`                INT UNSIGNED COMMENT 'Number of seatbelts fitted, PSV only',
    `last_seatbelt_installation_check_date`     DATE COMMENT 'Date of last seatbelt installation check, PSV only',
    `seatbelt_installation_check_date`          BOOLEAN COMMENT 'Whether seatbelt installation check date was provided',
    `emission_standard`                         VARCHAR(50) COMMENT 'Emission standard applied, e.g. Euro 3, Euro 4, Euro VI',
    `fuel_type`                                 VARCHAR(30) COMMENT 'Fuel type for emissions testing, e.g. diesel, gas-cng, petrol, full electric',
    `modification_type_used`                    VARCHAR(100) COMMENT 'Type of modification used for emissions compliance',
    `smoke_test_k_limit_applied`                VARCHAR(100) COMMENT 'K-limit applied during smoke test',
    `particulate_trap_fitted`                   VARCHAR(100) COMMENT 'Details of particulate trap fitted',
    `particulate_trap_serial_number`            VARCHAR(100) COMMENT 'Serial number of the particulate trap',
    `mod_type_code`                             VARCHAR(10) COMMENT 'Modification type code, if applicable',
    `mod_type_description`                      VARCHAR(100) COMMENT 'Modification type description, if applicable',
    `central_docs_issue_required`               BOOLEAN COMMENT 'Whether central documentation issue is required',
    `central_docs_notes`                        TEXT COMMENT 'Notes for central documentation',
    `central_docs_reasons_for_issue`            JSON COMMENT 'JSON array of reasons for central documentation issue',
    `load_status_vehicle_load_status`           VARCHAR(40) COMMENT 'Vehicle load status at time of test, e.g. unladen, fully laden',
    `load_status_unladen_body_type`             VARCHAR(30) COMMENT 'Unladen body type, if vehicle load status is unladen',
    `load_status_other_unladen_body_type`       VARCHAR(200) COMMENT 'Free-text unladen body type, if unladen body type is other',
    `load_status_reason_for_not_loading`        VARCHAR(30) COMMENT 'Reason the vehicle was not loaded for test',
    `load_status_other_reason_for_not_loading`  VARCHAR(200) COMMENT 'Free-text reason for not loading, if reason for not loading is other',
    `load_status_partially_laden_reason`        VARCHAR(200) COMMENT 'Reason for partial loading, if vehicle load status is partially laden',
    `deletion_flag`                             VARCHAR(10) COMMENT 'Whether this test type record has been soft-deleted',
    `created_at`                                DATETIME(3) COMMENT 'The Date and Time the test type record was created in the source system',
    `last_updated_at`                           DATETIME(3) COMMENT 'The Date and Time the test type record was last updated in the source system',
    PRIMARY KEY (`id`),
    CONSTRAINT `fk_test_type_test_result_id` FOREIGN KEY (`test_result_id`) REFERENCES `test_result` (`id`),
    INDEX `idx_test_type_test_result_id` (`test_result_id` ASC) COMMENT 'Supports efficient lookups of all test types within a test result',
    INDEX `idx_test_type_test_type_id` (`test_type_id` ASC) COMMENT 'Supports efficient joins to test_type reference data',
    INDEX `idx_test_type_test_number` (`test_number` ASC) COMMENT 'Supports efficient lookups by test number',
    INDEX `idx_test_type_certificate_number` (`certificate_number` ASC) COMMENT 'Supports efficient lookups by certificate number'
)
    ENGINE = InnoDB
    COMMENT = 'Individual test type executions within a test result, capturing the outcome, certificate details and emissions data for each test performed';

CREATE TABLE IF NOT EXISTS `test_result_defect`
(
    `id`                            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Surrogate key ID',
    `test_result_test_type_id`      BIGINT UNSIGNED NOT NULL COMMENT 'Test result test type surrogate key ID. References `[test_result_test_type].[id]`',
    `defect_deficiency_id`          BIGINT UNSIGNED NOT NULL COMMENT 'Defect deficiency surrogate key ID. References `[defect_deficiency].[id]`. JOIN through defect_deficiency -> defect_item -> defect_category for full defect details.',
    `prs`                           BOOLEAN COMMENT 'Whether the defect was marked as a PRS (pass after rectification at station)',
    `prohibition_issued`            BOOLEAN COMMENT 'Whether a prohibition was issued for this specific defect',
    `location_vertical`             VARCHAR(20) COMMENT 'Vertical location of the defect on the vehicle',
    `location_horizontal`           VARCHAR(20) COMMENT 'Horizontal location of the defect on the vehicle',
    `location_lateral`              VARCHAR(20) COMMENT 'Lateral location of the defect on the vehicle',
    `location_longitudinal`         VARCHAR(20) COMMENT 'Longitudinal location of the defect on the vehicle',
    `location_row_number`           INT UNSIGNED COMMENT 'Row number where the defect was found, PSV seating',
    `location_seat_number`          INT UNSIGNED COMMENT 'Seat number where the defect was found, PSV seating',
    `location_axle_number`          INT UNSIGNED COMMENT 'Axle number where the defect was found',
    `additional_information_notes`  TEXT COMMENT 'Additional notes recorded about the defect',
    PRIMARY KEY (`id`),
    CONSTRAINT `fk_defect_test_type_id` FOREIGN KEY (`test_result_test_type_id`) REFERENCES `test_result_test_type` (`id`),
    CONSTRAINT `fk_defect_deficiency_id` FOREIGN KEY (`defect_deficiency_id`) REFERENCES `defect_deficiency` (`id`),
    INDEX `idx_defect_test_type_id` (`test_result_test_type_id` ASC) COMMENT 'Supports efficient lookups of all defects within a test type',
    INDEX `idx_defect_deficiency_id` (`defect_deficiency_id` ASC) COMMENT 'Supports efficient joins to defect reference data'
)
    ENGINE = InnoDB
    COMMENT = 'Defects recorded during a test type execution. JOIN to defect_deficiency -> defect_item -> defect_category for IM reference details. Stores per-result data: prs, prohibition, location.';

CREATE TABLE IF NOT EXISTS `test_result_custom_defect`
(
    `id`                            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Surrogate key ID',
    `test_result_test_type_id`      BIGINT UNSIGNED NOT NULL COMMENT 'Test result test type surrogate key ID. References `[test_result_test_type].[id]`',
    `reference_number`              VARCHAR(50) NOT NULL COMMENT 'Custom defect reference number',
    `defect_name`                   VARCHAR(500) NOT NULL COMMENT 'Name of the custom defect',
    `defect_notes`                  TEXT NOT NULL COMMENT 'Notes describing the custom defect',
    PRIMARY KEY (`id`),
    CONSTRAINT `fk_custom_defect_test_type_id` FOREIGN KEY (`test_result_test_type_id`) REFERENCES `test_result_test_type` (`id`),
    INDEX `idx_custom_defect_test_type_id` (`test_result_test_type_id` ASC) COMMENT 'Supports efficient lookups of all custom defects within a test type'
)
    ENGINE = InnoDB
    COMMENT = 'Custom defects recorded by specialist testers during IVA and MSVA test type executions';

CREATE TABLE IF NOT EXISTS `test_result_required_standard`
(
    `id`                            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Surrogate key ID',
    `test_result_test_type_id`      BIGINT UNSIGNED NOT NULL COMMENT 'Test result test type surrogate key ID. References `[test_result_test_type].[id]`',
    `section_number`                VARCHAR(20) NOT NULL COMMENT 'Section number of the required standard',
    `section_description`           VARCHAR(500) NOT NULL COMMENT 'Description of the section',
    `rs_number`                     INT UNSIGNED NOT NULL COMMENT 'Required standard number within the section',
    `required_standard`             VARCHAR(500) NOT NULL COMMENT 'Description of the required standard',
    `ref_calculation`               VARCHAR(100) NOT NULL COMMENT 'Reference calculation for the required standard',
    `additional_info`               BOOLEAN NOT NULL COMMENT 'Whether additional information applies to this standard',
    `additional_notes`              TEXT COMMENT 'Additional notes for the required standard, if applicable',
    `inspection_types`              JSON COMMENT 'JSON array of inspection types this standard applies to',
    `prs`                           BOOLEAN NOT NULL COMMENT 'Whether PRS (pass after rectification at station) applies',
    PRIMARY KEY (`id`),
    CONSTRAINT `fk_required_standard_test_type_id` FOREIGN KEY (`test_result_test_type_id`) REFERENCES `test_result_test_type` (`id`),
    INDEX `idx_required_standard_test_type_id` (`test_result_test_type_id` ASC) COMMENT 'Supports efficient lookups of all required standards within a test type'
)
    ENGINE = InnoDB
    COMMENT = 'Required standards assessed during IVA and MSVA test type executions, tracking compliance against individual standards';
